let beforeExecute = null;
let trackReads=false, outstandingReads=0, peakReads=0;
class Statement {
  constructor(query, args = []) { this.query = query; this.args = args; }
  bind(...args) { return new Statement(this.query, args); }
  async first() { return sql.prepare(this.query).get(...this.args) ?? null; }
  async all() { if(trackReads){outstandingReads++;peakReads=Math.max(peakReads,outstandingReads);await Promise.resolve();outstandingReads--;} return { results: sql.prepare(this.query).all(...this.args), success: true }; }
  execute() { beforeExecute?.(this); const r = sql.prepare(this.query).run(...this.args); return { success: true, meta: { changes: Number(r.changes) } }; }
  async run() { return this.execute(); }
}
const DB = { prepare: q => new Statement(q), async batch(statements) { sql.exec('BEGIN'); try { const out = statements.map(s => s.execute()); sql.exec('COMMIT'); return out; } catch (e) { sql.exec('ROLLBACK'); throw e; } } };
