test('Soul references require both memberships and recheck revoked permission on every read', async () => {
  const stamp=new Date().toISOString(), rid='fixture-revision-0001';
  sql.prepare('INSERT INTO x1_group_souls VALUES (?,?,?,?,?,?,?)').run(soulId,groupId,1,rid,'DRAFT',stamp,stamp);
  sql.prepare('INSERT INTO x1_soul_revisions VALUES (?,?,?,?,?,?,?,?,?,?,?)').run(rid,soulId,1,'Fixture method','close > 0','Fixture summary with explicit source gaps.','{}','Initial fixture','alpha','alpha_body',stamp);
  const sent=await call({action:'send',threadId:tid,text:'Permitted methodology reference.',soulId,revision:1,requestId:'message-reference-fixture-001'});
  assert.equal(sent.status,200);
  assert.equal((await call(undefined,'beta',{view:'thread',threadId:tid})).data.messages.find(m=>m.id===sent.data.messageId).reference.title,'Fixture method');
  assert.equal((await call({action:'bookmark',kind:'SOUL',targetId:soulId,active:true},'beta')).status,200);
  sql.prepare('DELETE FROM x1_memberships WHERE group_id=? AND subject=?').run(groupId,'beta');
  assert.equal((await call(undefined,'beta',{view:'thread',threadId:tid})).data.messages.find(m=>m.id===sent.data.messageId).reference.unavailable,true);
  assert.equal((await call(undefined,'beta')).data.bookmarks.length,0);
  assert.equal((await call({action:'send',threadId:tid,text:'Revoked reference.',soulId,revision:1,requestId:'message-reference-fixture-002'})).status,404);
  assert.equal((await call({action:'bookmark',kind:'SOUL',targetId:soulId,active:false},'beta')).status,200);
});
test('Group discussions are current-member scoped, idempotent, threaded and source-validating', async () => {
  const content={action:'discussion',groupId,text:'Fixture research observation @outsider_body',sourceUrl:'https://example.invalid/report',sourceAsOf:'2026-11-01',requestId:'discussion-fixture-0001'};
  const made=await call(content);assert.equal(made.status,200);
  assert.equal((await call(content)).data.discussionId,made.data.discussionId);
  assert.equal((await call({...content,text:'Changed payload.'})).status,409);
  assert.equal((await call({...content,requestId:'discussion-fixture-0002',sourceUrl:'javascript:alert(1)'})).status,400);
  assert.equal((await call({...content,requestId:'discussion-fixture-0003',sourceAsOf:'2026-02-31'})).status,400);
  assert.equal((await call({...content,requestId:'discussion-fixture-0004'},'gamma')).status,404);
  assert.equal((await call({...content,requestId:'discussion-fixture-0005',parentId:made.data.discussionId,text:'An allowed reply.'},'outsider')).status,200);
  assert.equal((await call({action:'remove-discussion',groupId,discussionId:made.data.discussionId},'outsider')).status,404);
  assert.equal((await call({action:'remove-discussion',groupId,discussionId:made.data.discussionId})).status,200);
  assert.equal((await call(undefined,'outsider',{view:'group',groupId})).data.discussions[0].text,'');
  assert.ok((await call(undefined,'outsider')).data.notifications.some(n=>n.kind==='MENTION'));
});
