test('Role revocation between authorization and SQL cannot publish a directory or discussion', async () => {
  sql.prepare('UPDATE x1_memberships SET role=? WHERE group_id=? AND subject=?').run('ADMIN',groupId,'outsider');
  beforeExecute=statement=>{if(statement.query.startsWith('INSERT INTO x2_group_directory')){beforeExecute=null;sql.prepare('UPDATE x1_memberships SET role=? WHERE group_id=? AND subject=?').run('VIEWER',groupId,'outsider');}};
  assert.equal((await call({action:'group-directory',groupId,handle:'race_changed_group',discoverable:true},'outsider')).status,409);
  assert.equal(sql.prepare('SELECT handle FROM x2_group_directory WHERE group_id=?').get(groupId).handle,'fixture_group');
  beforeExecute=statement=>{if(statement.query.startsWith('INSERT OR IGNORE INTO x2_discussions')){beforeExecute=null;sql.prepare('DELETE FROM x1_memberships WHERE group_id=? AND subject=?').run(groupId,'gamma');}};
  assert.equal((await call({action:'discussion',groupId,text:'A revoked contribution.',requestId:'race-discussion-fixture-001'},'gamma')).status,409);
  assert.equal(sql.prepare('SELECT count(*) n FROM x2_discussions WHERE author=?').get('gamma').n,0);
  assert.equal((await call({action:'accept-invitation',invitationId:'fixture-invite-0001'},'gamma')).status,404);
});
