test('Message policy, scoped report, export and account erasure retain no unrelated private messages', async () => {
  assert.equal((await call(prefs({messages:'NONE'}),'beta')).status,200);
  assert.equal((await call({action:'send',threadId:tid,text:'Policy denied.',requestId:'policy-message-fixture-001'})).status,404);
  assert.equal((await call({action:'report',kind:'MESSAGE',targetId:secondMessage,reason:'Fixture report for authorized review.'},'outsider')).status,404);
  assert.equal((await call({action:'report',kind:'MESSAGE',targetId:secondMessage,reason:'Fixture report for authorized review.'})).status,200);
  const out=await service.exportSocial('alpha'), stranger=await service.exportSocial('outsider');
  assert.ok(out.x2_messages.length>0); assert.equal(stranger.x2_messages.length,0); assert.equal(stranger.x2_social_reports.length,0);
  await DB.batch(service.socialEraseStatements('alpha'));
  assert.equal(sql.prepare('SELECT count(*) n FROM x2_messages').get().n,0);
  assert.equal(sql.prepare('SELECT count(*) n FROM x1_bodies WHERE subject=?').get('beta').n,1);
  assert.equal(sql.prepare('PRAGMA integrity_check').get().integrity_check,'ok');
});
